import{_ as a}from"./chunks/flight_termination_logic_diagram.Dsd1Xat6.js";import{_ as t,c as i,o as r,al as o}from"./chunks/framework.D8UyiDWg.js";const u=JSON.parse('{"title":"飞行终止配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/advanced_config/flight_termination.md","filePath":"zh/advanced_config/flight_termination.md"}'),n={name:"zh/advanced_config/flight_termination.md"};function l(s,e,c,h,m,f){return r(),i("div",null,e[0]||(e[0]=[o('<h1 id="飞行终止配置" tabindex="-1">飞行终止配置 <a class="header-anchor" href="#飞行终止配置" aria-label="Permalink to &quot;飞行终止配置&quot;">​</a></h1><p>The <em>Flight termination</em> <a href="./../config/safety.html#failsafe-actions">failsafe action</a> irreversibly turns off controllers and sets PWM values to their parameter configured failsafe values.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight termination differs from the <a href="./../config/safety.html#kill-switch">Kill action</a> in that it is permanent until after reboot.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is <em>not</em> an independent <em>Flight Termination System</em>. 如果断电或者自驾仪完全失控，失效保护设备则不会触发。</p></div><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><h3 id="termination-triggers" tabindex="-1">Termination Triggers <a class="header-anchor" href="#termination-triggers" aria-label="Permalink to &quot;Termination Triggers&quot;">​</a></h3><p>Termination may be triggered by:</p><ul><li><a href="./../config/safety.html">Safety checks</a> for RC Loss, geofence violation, and so on (on any vehicle type or in any flight mode).</li><li><a href="./../config/safety.html#failure-detector">Failure Detector</a> trigger</li><li>RC termination switch (mapped to an RC channel using <a href="./../advanced_config/parameter_reference.html#RC_MAP_TERM_SW">RC_MAP_TERM_SW</a>).</li><li>The MAVLink <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FLIGHTTERMINATION" target="_blank" rel="noreferrer">MAV_CMD_DO_FLIGHTTERMINATION</a> MAVLink command from a GCS or companion computer (see <a href="#mavlink-trigger">MAVLink Trigger</a> below).</li></ul><p>飞行终止是无法取消的。 在飞行终止触发后，您应尽快拔下电池。 您需要在重启载具或重新上电后才能再次使用。</p><h3 id="termination-actions" tabindex="-1">Termination Actions <a class="header-anchor" href="#termination-actions" aria-label="Permalink to &quot;Termination Actions&quot;">​</a></h3><p>When <em>Flight termination</em> is activated, PX4 simultaneously turns off all controllers and sets all PWM outputs to their failsafe values.</p><p>根据所连接的设备，PWM 故障保护输出可以用来完成以下动作：</p><ul><li>Deploy a <a href="./../peripherals/parachute.html">parachute</a>.</li><li>伸展可伸缩起落架。</li><li>将连接了 PWM 的云台移动到安全的方向（或将它回收）以保护摄像机。</li><li>触发一个可充气的装置，如安全气囊。</li><li>触发警报。</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>PX4 does not know what safety devices are attached - it just applies a predefined set of PWM values to its outputs.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Failsafe values are applied to all outputs on termination. 无法配置电机或特定安全装置为独立的特定时间（或其他方式）触发。</p></div><h2 id="硬件配置" tabindex="-1">硬件配置 <a class="header-anchor" href="#硬件配置" aria-label="Permalink to &quot;硬件配置&quot;">​</a></h2><p>Any <em>safety device(s)</em> (e.g. a <a href="./../peripherals/parachute.html">parachute</a>) that can be triggered by changing a PWM value can be used, and may be connected to any free PWM port (both MAIN and AUX).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you&#39;re using Pixhawk-series board you will have to separately power the servo rail (i.e. from a 5V BEC, which is often also available from your ESC).</p></div><h2 id="软件配置" tabindex="-1">软件配置 <a class="header-anchor" href="#软件配置" aria-label="Permalink to &quot;软件配置&quot;">​</a></h2><p>The <a href="./../config/safety.html">Safety</a> topic explains how to set the <em>flight termination</em> as the <a href="./../config/safety.html#failsafe-actions">failsafe action</a> to be performed for particular failsafe check.</p><p>The <a href="./../config/safety.html#failure-detector">Failure Detector</a> can also (optionally) be configured to trigger flight termination if the vehicle flips (exceeds a certain attitude) or if failure is detected by an external automatic trigger system (ATS):</p><ul><li>Enable the failure detector during flight by setting <a href="./../advanced_config/parameter_reference.html#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM=0</a>.</li><li><a href="./../config/safety.html#attitude-trigger">Safety &gt; Failure Detector &gt; Attitude Trigger</a> explains how to configure the attitude limits that trigger <em>Flight termination</em>.<div class="info custom-block"><p class="custom-block-title">INFO</p><p>During <em>takeoff</em> excessive attitutes will trigger <em>lockdown</em> (kill motors, but not launch parachute) rather than flight termination. This is always enabled, irrespective of the value of <code>CBRK_FLIGHTTERM</code>.</p></div></li></ul><p>:::</p><ul><li><a href="./../config/safety.html#external-automatic-trigger-system-ats">Safety &gt; External Automatic Trigger System (ATS)</a> explains how to configure an external trigger system.</li></ul><p>对于每个与安全装置相连的 MAIN 输出，其中“n”指 PWM 端口号，设置：</p><ul><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_DIS1">PWM_MAIN_DISn</a> to the device&#39;s &quot;OFF&quot; PWM value.</li><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_FAIL1">PWM_MAIN_FAILn</a> to the device&#39;s &quot;ON&quot; PWM value.</li></ul><p>对于每个与安全装置相连的 AUX 输出，其中“n”指 PWM 端口号，设置：</p><ul><li><a href="./../advanced_config/parameter_reference.html#PWM_AUX_DIS1">PWM_AUX_DIS1</a> to the device&#39;s &quot;OFF&quot; PWM value.</li><li><a href="./../advanced_config/parameter_reference.html#PWM_AUX_FAIL1">PWM_AUX_FAILn</a> to the device&#39;s &quot;ON&quot; PWM value.</li></ul><p>Finally, set the <code>PWM_AUX_FAILn</code> and <code>PWM_MAIN_FAILn</code> PWM values for any motors.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight termination via ATS only works if <code>drivers/pwm_input</code> is included in the firmware for your board. If not, you need to add it manually to your board configuration using <a href="./../hardware/porting_guide_config.html#px4-menuconfig-setup">boardconfig</a>.</p></div><h2 id="mavlink-trigger" tabindex="-1">MAVLink Trigger <a class="header-anchor" href="#mavlink-trigger" aria-label="Permalink to &quot;MAVLink Trigger&quot;">​</a></h2><p>The <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FLIGHTTERMINATION" target="_blank" rel="noreferrer">MAV_CMD_DO_FLIGHTTERMINATION</a> command can be used to trigger Flight termination from a ground station or companion computer.</p><p>This is sent, for example, when you call the <a href="https://mavsdk.mavlink.io/main/en/cpp/api_reference/classmavsdk_1_1_action.html#classmavsdk_1_1_action_1a47536c4a4bc8367ccd30a92eb09781c5" target="_blank" rel="noreferrer">MAVSDK Action plugin</a> <code>terminate()</code> or <code>terminate_async()</code> methods.</p><h2 id="逻辑图解" tabindex="-1">逻辑图解 <a class="header-anchor" href="#逻辑图解" aria-label="Permalink to &quot;逻辑图解&quot;">​</a></h2><p>下图显示了飞行终止的逻辑流程。</p><p><img src="'+a+'" alt="Logic diagram"></p>',36)]))}const g=t(n,[["render",l]]);export{u as __pageData,g as default};
